-- =====================================================================
-- SQL Server Express / T-SQL Data Analytics Teaching Dataset
-- Generated with Faker (en_GB locale)
-- Tables: regions, sales_people, customers, products, sales
-- Sales rows: 5000, date range: 2002-01-01 to 2026-08-30
-- =====================================================================
-- SQL Server notes:
--   * SERIAL has been converted to INT IDENTITY(1,1).
--   * Explicit source IDs are loaded using SET IDENTITY_INSERT.
--   * PostgreSQL CASCADE and sequence functions have been removed/replaced.
--   * Sales data is already split into batches below SQL Server's 1,000-row
--     VALUES constructor limit.
-- =====================================================================

SET XACT_ABORT ON;
BEGIN TRANSACTION;

-- Drop existing tables (children before parents)
DROP TABLE IF EXISTS dbo.sales;
DROP TABLE IF EXISTS dbo.customers;
DROP TABLE IF EXISTS dbo.sales_people;
DROP TABLE IF EXISTS dbo.products;
DROP TABLE IF EXISTS dbo.regions;

-- =====================================================================
-- Schema
-- =====================================================================

CREATE TABLE dbo.regions (
    region_id    INT IDENTITY(1,1) PRIMARY KEY,
    region_name  VARCHAR(60) NOT NULL UNIQUE,
    nation       VARCHAR(30) NOT NULL
);

CREATE TABLE dbo.sales_people (
    sales_person_id  INT IDENTITY(1,1) PRIMARY KEY,
    first_name       VARCHAR(60) NOT NULL,
    last_name        VARCHAR(60) NOT NULL,
    email            VARCHAR(120) NOT NULL UNIQUE,
    hire_date        DATE NOT NULL,
    region_id        INT NOT NULL REFERENCES dbo.regions(region_id)
);

CREATE TABLE dbo.customers (
    customer_id    INT IDENTITY(1,1) PRIMARY KEY,
    first_name     VARCHAR(60) NOT NULL,
    last_name      VARCHAR(60) NOT NULL,
    email          VARCHAR(120) NOT NULL UNIQUE,
    city           VARCHAR(80) NOT NULL,
    postcode       VARCHAR(10) NOT NULL,
    phone_number   VARCHAR(25) NULL,
    region_id      INT NOT NULL REFERENCES dbo.regions(region_id),
    signup_date    DATE NOT NULL
);

CREATE TABLE dbo.products (
    product_id     INT IDENTITY(1,1) PRIMARY KEY,
    product_name   VARCHAR(100) NOT NULL,
    category       VARCHAR(60) NOT NULL,
    unit_price     NUMERIC(10,2) NOT NULL,
    unit_cost      NUMERIC(10,2) NOT NULL
);

CREATE TABLE dbo.sales (
    sale_id          INT IDENTITY(1,1) PRIMARY KEY,
    sale_date        DATE NOT NULL,
    sales_person_id  INT NOT NULL REFERENCES dbo.sales_people(sales_person_id),
    customer_id      INT NOT NULL REFERENCES dbo.customers(customer_id),
    product_id       INT NOT NULL REFERENCES dbo.products(product_id),
    quantity         INT NOT NULL,
    unit_price       NUMERIC(10,2) NOT NULL,
    discount_pct     NUMERIC(4,2) NOT NULL DEFAULT 0,
    total_amount     NUMERIC(12,2) NOT NULL
);

-- Helpful indexes for analytics queries
CREATE INDEX idx_sales_date ON dbo.sales(sale_date);
CREATE INDEX idx_sales_person ON dbo.sales(sales_person_id);
CREATE INDEX idx_sales_customer ON dbo.sales(customer_id);
CREATE INDEX idx_sales_product ON dbo.sales(product_id);

-- =====================================================================
-- Data: regions
-- =====================================================================
SET IDENTITY_INSERT dbo.regions ON;

